UPDATE prompt_versions
SET prompt_content = #{promptContent}, description = #{description}, updated_at = NOW()
WHERE id = #{id}

UPDATE prompt_versions
SET status = 'ACTIVE', is_default = 1, activated_at = NOW()
WHERE id = #{id}

UPDATE prompt_ab_tests
SET status = 'COMPLETED', ended_at = NOW(), winner_version_id = #{winnerVersionId}
WHERE id = #{id}
